  "正在準備人聲分離…": { en: "Preparing vocal separation…", ja: "ボーカル分離を準備中…", fr: "Préparation de la séparation des voix…", de: "Gesangstrennung wird vorbereitet…", it: "Preparazione della separazione vocale…", es: "Preparando la separación de voz…" , "pt-BR": "Preparando a separação de vocais…", "ko": "보컬 분리 준비 중…", "ru": "Подготовка к отделению вокала…", "id": "Menyiapkan pemisahan vokal…", "vi": "Đang chuẩn bị tách giọng hát…", "th": "กำลังเตรียมแยกเสียงร้อง…", "tr": "Vokal ayrıştırma hazırlanıyor…", "nl": "Zangscheiding voorbereiden…", "pl": "Przygotowywanie separacji wokalu…", "uk": "Підготовка до відокремлення вокалу…", "hi": "गायन की आवाज़ अलग करने की तैयारी हो रही है…", "bn": "কণ্ঠস্বর আলাদা করার প্রস্তুতি চলছে…", "ms": "Sedang menyediakan pemisahan vokal…", "fil": "Inihahanda ang paghihiwalay ng boses…", "sv": "Förbereder sångseparering…" },
